import random
M=(1<<64)-1
L8=0x0101010101010101;H8=0x8080808080808080;M16=0x00FF00FF00FF00FF;L16=0x0001000100010001
def nz(x,fixed): return ((((x|H8)-L8)&M)|(x if fixed else 0))&H8
def cnt(x,fx): return (((nz(x,fx)>>7)*L8)&M)>>56
def sm(x):
  p=(x&M16)+((x>>8)&M16); return (((p*L16)&M)>>48)&0xFFFF
def code(a,f,fx): return (a>>1)+(cnt(f,fx)<<8)+sm(f)
def spec(a,f):
  bs=[(f>>(8*i))&0xFF for i in range(8)]; return a//2+256*sum(1 for b in bs if b)+sum(bs)
bad=0;n=0
def chk(a,f):
  global bad,n
  n+=1
  t=code(a,f,True)
  if t>M or t!=spec(a,f): bad+=1
for i in range(8):
